// HAND-WRITTEN TEST — NOT generated by openapi-generator. The zz_ prefix and
// _test.go suffix keep gen.sh from overwriting it.
//
// It locks in the decoders tools/fixoneof patches into the two wrappers every
// discovery run depends on: the discovered item's payload, and the checkpoint
// Core replays on each call as a metadata attribute.
package v2

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"
)

func roundTrip[T any](t *testing.T, in T) T {
	t.Helper()
	b, e := json.Marshal(in)
	if e != nil {
		t.Fatal(e)
	}
	var out T
	if e = json.Unmarshal(b, &out); e != nil {
		t.Fatalf("%s: %v", b, e)
	}
	return out
}

func TestDiscoveredItemPayloadRoundTrip(t *testing.T) {
	cert := NewDiscoveredCertificateDto(RESOURCE_CERTIFICATES, "YWJj")
	got := roundTrip(t, DiscoveredCertificateDtoAsDiscoveredItemPayload(cert))
	if got.DiscoveredKeyDto != nil || got.DiscoveredCertificateDto == nil || got.DiscoveredCertificateDto.CertificateData != "YWJj" {
		t.Fatalf("certificate: %+v", got)
	}

	key := NewDiscoveredKeyDto(RESOURCE_KEYS, KEYTYPE_PUBLIC, KEYALGORITHM_RSA)
	key.SetLength(2048)
	key.SetPublicKey("cHVi")
	got = roundTrip(t, DiscoveredKeyDtoAsDiscoveredItemPayload(key))
	if got.DiscoveredCertificateDto != nil || got.DiscoveredKeyDto == nil {
		t.Fatalf("key: %+v", got)
	}
	k := got.DiscoveredKeyDto
	if k.Type != KEYTYPE_PUBLIC || k.Algorithm != KEYALGORITHM_RSA || k.GetLength() != 2048 || k.GetPublicKey() != "cHVi" {
		t.Fatalf("key fields: %+v", k)
	}
}

// p256Identifier is the DER AlgorithmIdentifier {id-ecPublicKey, prime256v1}, in base64.
const p256Identifier = "MBMGByqGSM49AgEGCCqGSM49AwEH"

func TestDiscoveredItemPayloadCarriesAPrivateKeysAlgorithmIdentifier(t *testing.T) {
	key := NewDiscoveredKeyDto(RESOURCE_KEYS, KEYTYPE_PRIVATE, KEYALGORITHM_ECDSA)
	key.SetAlgorithmIdentifier(p256Identifier)
	payload := DiscoveredKeyDtoAsDiscoveredItemPayload(key)

	wire, err := json.Marshal(payload)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(wire), `"algorithmIdentifier":"`+p256Identifier+`"`) {
		t.Fatalf("wire form lacks algorithmIdentifier: %s", wire)
	}
	if got := roundTrip(t, payload).DiscoveredKeyDto; got == nil || got.GetAlgorithmIdentifier() != p256Identifier {
		t.Fatalf("decoded key: %+v", got)
	}
}

func TestDiscoveredItemPayloadRefusesUnknownResource(t *testing.T) {
	for _, raw := range []string{`{"resource":"widgets","certificateData":"YWJj"}`, `{"certificateData":"YWJj"}`} {
		var p DiscoveredItemPayload
		if e := json.Unmarshal([]byte(raw), &p); e == nil || !strings.Contains(e.Error(), "unknown resource") {
			t.Fatalf("%s: %v", raw, e)
		}
	}
}

func TestCheckpointMetadataRoundTrip(t *testing.T) {
	v := NewMetadataAttributeV3("d0235059-d463-4937-a2aa-20efdd000001", "checkpoint", 3, ATTRIBUTETYPE_META, ATTRIBUTECONTENTTYPE_STRING, *NewMetadataAttributeProperties("Checkpoint", false), ATTRIBUTEVERSION_V3)
	v.Content = []BaseAttributeContentDtoV3{StringAttributeContentV3AsBaseAttributeContentDtoV3(NewStringAttributeContentV3(`{"sequence":2}`, ATTRIBUTECONTENTTYPE_STRING))}
	in := MetadataAttributeV3AsMetadataAttribute(v)
	got := roundTrip(t, in)
	if got.MetadataAttributeV2 != nil || got.MetadataAttributeV3 == nil || len(got.MetadataAttributeV3.Content) != 1 {
		t.Fatalf("%+v", got)
	}
	if s := got.MetadataAttributeV3.Content[0].StringAttributeContentV3; s == nil || s.Data != `{"sequence":2}` {
		t.Fatalf("content: %+v", got.MetadataAttributeV3.Content[0])
	}
	if !reflect.DeepEqual(roundTrip(t, got), got) {
		t.Fatal("a second round trip changed the checkpoint")
	}
}
